from flask import Flask, jsonify, request, session, redirect

app = Flask(__name__)
app.secret_key = "legacy-secret"

USERS = {
    "1": {"id": 1, "name": "Alice", "role": "admin"},
    "2": {"id": 2, "name": "Bob", "role": "user"},
}

@app.get("/health")
def health():
    return jsonify({"status": "ok"})

@app.post("/login")
def login():
    b = request.get_json(silent=True) or {}
    u = USERS.get(str(b.get("user_id", "")))
    if not u:
        return jsonify({"error": "invalid_credentials"}), 401
    session["user_id"] = u["id"]
    return jsonify({"message": "logged_in", "user": u})

@app.get("/me")
def me():
    uid = session.get("user_id")
    if not uid:
        return jsonify({"error": "not_authenticated"}), 401
    return jsonify(USERS[str(uid)])

@app.get("/admin")
def admin():
    uid = session.get("user_id")
    if not uid:
        return jsonify({"error": "not_authenticated"}), 401
    if USERS[str(uid)]["role"] != "admin":
        return jsonify({"error": "forbidden"}), 403
    return jsonify({"message": "admin_ok"})

@app.get("/old-home")
def old_home():
    return redirect("/health", 302)
